@push('scripts')<script>const balanceUrl='{{ route('api.accounts.balance',$account) }}';setInterval(async()=>{try{const d=await fetch(balanceUrl).then(r=>r.json());document.querySelector('#balance').textContent='₱'+Number(d.balance).toLocaleString('en-PH',{minimumFractionDigits:2});document.querySelector('#balance-status').textContent=d.low_balance?'⚠ Low balance alert':'Account {{ $account->account_number }}';document.querySelector('#balance-status').style.color=d.low_balance?'#ffd166':'';}catch(e){console.warn('Polling failed',e)}},5000);</script>@endpush
